import puppeteer from "puppeteer";
import { amountToWords } from "../utils/numberToWords.js";

/**
 * voucherPdfRenderer.service.js
 * ================================
 * Everything - shared styles, layout partials, and all 6 voucher templates -
 * lives in this one file as plain JS functions that return HTML strings.
 *
 * CHANGE LOG (this revision):
 * - Logo box replaced with a real <img> tag (LOGO_BASE64 below). Currently
 *   a placeholder — swap in the real base64 string once the logo file is
 *   provided, nothing else needs to change.
 * - .voucher-title CSS corrected to match the reference design: white
 *   background, blue text, blue bottom border (was gray background/black
 *   text before).
 * - Header layout tightened to match reference: logo + company block share
 *   a row, contact details in a lighter gray under the name.
 */

// ---------- tiny helpers ----------

/** Escapes user-entered text (ledger names, narration, etc.) before dropping into HTML */
function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function money(n) {
  return (Number(n) || 0).toFixed(2);
}

// ---------- logo ----------

/**
 * PLACEHOLDER — replace with the real logo as a base64 data URI, e.g.:
 *   "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAA..."
 * Generate it from the logo file with:
 *   node -e "console.log('data:image/png;base64,' + require('fs').readFileSync('logo.png').toString('base64'))"
 * Until this is set, the header falls back to a plain text box so nothing
 * breaks — but it won't visually match the reference design yet.
 */
const LOGO_BASE64 = "data:image/jpeg;base64,";

function logoHtml() {
  if (LOGO_BASE64) {
    return `<img src="${LOGO_BASE64}" class="company-logo-img" alt="logo" />`;
  }
  // Fallback so rendering never breaks before the real logo is wired in
  return `<div class="company-logo-box">SAI<br/>COMPUTECH</div>`;
}

